def solve():
    solutions = []
    for a in range(1, 15):
        c_max = int(2012 / (a**2)) + 2
        for c in range(a, c_max + 1):
            for b in range(a, c + 1):
                if a**3 * (b**3 + c**3) == 2012 * (a*b*c + 2):
                    solutions.append((a, b, c))
    return solutions

print(solve())

